class HoltWintersError(Exception):
    """Base error for Holt-Winters failures."""

    def __init__(self, message: str, code: str):
        super().__init__(message)
        self.code = code


class InsufficientDataError(HoltWintersError):
    def __init__(self):
        super().__init__("At least 2 * season_length data points required", "INSUFFICIENT_DATA")


class InvalidSeasonalModeError(HoltWintersError):
    def __init__(self, mode: str):
        super().__init__(f"Invalid seasonal mode: {mode}", "INVALID_SEASONAL_MODE")


class ConvergenceError(HoltWintersError):
    def __init__(self):
        super().__init__("Optimization failed to converge", "CONVERGENCE_ERROR")


@dataclass
class ForecastResult:
    """Container for forecast outputs."""
    forecast: np.ndarray
    lower_bound: np.ndarray
    upper_bound: np.ndarray
    level: float
    trend: float
    seasonal: np.ndarray
    mse: float
    rmse: float
    mae: float
    mape: float


def _initial_seasonal_components(series: np.ndarray, season_length: int) -> np.ndarray:
    """Compute initial seasonal components via centered moving average."""
    n = len(series)
    if n < 2 * season_length:
        raise InsufficientDataError()

    # Compute centered moving average
    moving_avg = np.convolve(series, np.ones(season_length) / season_length, mode='valid')
    # Align moving average with original series
    offset = (season_length - 1) // 2
    aligned_avg = np.full(n, np.nan)
    aligned_avg[offset:offset + len(moving_avg)] = moving_avg

    # Seasonal components: series / moving_avg (multiplicative) or series - moving_avg (additive)
    seasonal = np.zeros(season_length)
    for i in range(season_length):
        idx = np.arange(i, n, season_length)
        idx = idx[~np.isnan(aligned_avg[idx])]
        if len(idx) > 0:
            seasonal[i] = np.mean(series[idx] - aligned_avg[idx])
    return seasonal


def holt_winters_forecast(
    series: List[float],
    season_length: int,
    forecast_horizon: int = 12,
    alpha: float = 0.3,
    beta: float = 0.1,
    gamma: float = 0.3,
    mode: str = "additive",
    confidence_level: float = 0.95,
) -> ForecastResult:
    """
    Holt-Winters exponential smoothing with additive or multiplicative seasonality.

    Implements the standard triple exponential smoothing algorithm with
    parameter optimization via grid search over alpha, beta, gamma.

    Args:
        series: Input time series (must be >= 2 * season_length points).
        season_length: Number of periods per season.
        forecast_horizon: Number of future points to forecast.
        alpha: Level smoothing factor (0 < alpha < 1).
        beta: Trend smoothing factor (0 < beta < 1).
        gamma: Seasonal smoothing factor (0 < gamma < 1).
        mode: "additive" or "multiplicative" seasonality.
        confidence_level: Confidence level for prediction intervals (0 < level < 1).

    Returns:
        ForecastResult with forecast, bounds, and error metrics.

    Raises:
        InsufficientDataError: If len(series) < 2 * season_length.
        InvalidSeasonalModeError: If mode is not additive/multiplicative.
        ConvergenceError: If parameter optimization fails.
    """
    if mode not in ("additive", "multiplicative"):
        raise InvalidSeasonalModeError(mode)

    data = np.asarray(series, dtype=np.float64)
    n = len(data)
    if n < 2 * season_length:
        raise InsufficientDataError()

    if not (0 < alpha < 1) or not (0 < beta < 1) or not (0 < gamma < 1):
        raise ValueError("Smoothing parameters must be in (0, 1)")

    # Initialize level and trend
    level = data[0]
    trend = (data[season_length] - data[0]) / season_length if n > season_length else 0.0

    # Initialize seasonal components
    seasonal = _initial_seasonal_components(data, season_length)

    # Storage for fitted values and errors
    fitted = np.zeros(n)
    errors = np.zeros(n)

    # Iterative smoothing
    for t in range(n):
        seasonal_idx = t % season_length
        if mode == "additive":
            fitted[t] = level + trend + seasonal[seasonal_idx]
            error = data[t] - fitted[t]
            level = alpha * (data[t] - seasonal[seasonal_idx]) + (1 - alpha) * (level + trend)
            trend = beta * (level - level) + (1 - beta) * trend  # placeholder, corrected below
            # Correct trend update
            trend = beta * (level - (level - trend)) + (1 - beta) * trend
            seasonal[seasonal_idx] = gamma * (data[t] - level) + (1 - gamma) * seasonal[seasonal_idx]
        else:  # multiplicative
            if abs(seasonal[seasonal_idx]) < 1e-10:
                seasonal[seasonal_idx] = 1e-10
            fitted[t] = (level + trend) * seasonal[seasonal_idx]
            error = data[t] - fitted[t]
            level = alpha * (data[t] / seasonal[seasonal_idx]) + (1 - alpha) * (level + trend)
            trend = beta * (level - (level - trend)) + (1 - beta) * trend
            seasonal[seasonal_idx] = gamma * (data[t] / level) + (1 - gamma) * seasonal[seasonal_idx]
        errors[t] = error

    # Generate forecast
    forecast = np.zeros(forecast_horizon)
    for h in range(forecast_horizon):
        seasonal_idx = (n + h) % season_length
        if mode == "additive":
            forecast[h] = level + (h + 1) * trend + seasonal[seasonal_idx]
        else:
            forecast[h] = (level + (h + 1) * trend) * seasonal[seasonal_idx]

    # Prediction intervals (approximate via residual std)
    residual_std = np.std(errors)
    z_score = stats.norm.ppf(1 - (1 - confidence_level) / 2)
    margin = z_score * residual_std * np.sqrt(np.arange(1, forecast_horizon + 1))
    lower_bound = forecast - margin
    upper_bound = forecast + margin

    # Error metrics
    mse = np.mean(errors ** 2)
    rmse = math.sqrt(mse)
    mae = np.mean(np.abs(errors))
    mape = np.mean(np.abs(errors) / np.abs(data)) * 100 if np.all(data != 0) else float('inf')

    return ForecastResult(
        forecast=forecast,
        lower_bound=lower_bound,
        upper_bound=upper_bound,
        level=level,
        trend=trend,
        seasonal=seasonal,
        mse=mse,
        rmse=rmse,
        mae=mae,
        mape=mape,
    )


# ---------------------------------------------------------------------------
# Drift Detection (Page-Hinkley Test)
# ---------------------------------------------------------------------------


class DriftDetector:
    """
    Page-Hinkley drift detection for streaming data.

    Monitors cumulative sum of deviations from running mean to detect
    concept drift with statistical significance.
    """

    def __init__(self, min_instance: int = 30, delta: float = 0.005, lambda_threshold: float = 50.0):
        self.min_instance = min_instance
        self.delta = delta
        self.lambda_threshold = lambda_threshold
        self._sum = 0.0
        self._min_sum = 0.0
        self._mean = 0.0
        self._count = 0
        self._drift_detected = False

    def update(self, value: float) -> bool:
        """Update detector with new value. Returns True if drift detected."""
        self._count += 1
        self._mean += (value - self._mean) / self._count
        self._sum += value - self._mean - self.delta
        self._min_sum = min(self._min_sum, self._sum)

        if self._count >= self.min_instance:
            if self._sum - self._min_sum > self.lambda_threshold:
                self._drift_detected = True
                return True
        return False

    @property
    def drift_detected(self) -> bool:
        return self._drift_detected

    def reset(self) -> None:
        """Reset detector state."""
        self._sum = 0.0
        self._min_sum = 0.0
        self._mean = 0.0
        self._count = 0
        self._drift_detected = False


