class TestHoltWintersBasics:
    """Core algorithm correctness tests."""

    def test_forecast_length(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=24)
        assert len(result.forecast) == 24
        assert len(result.lower_bound) == 24
        assert len(result.upper_bound) == 24

    def test_forecast_bounds_monotonic(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=12)
        assert np.all(result.lower_bound <= result.forecast)
        assert np.all(result.forecast <= result.upper_bound)

    def test_insufficient_data_raises(self):
        with pytest.raises(InsufficientDataError):
            holt_winters_forecast([1, 2, 3], season_length=12)

    def test_invalid_mode_raises(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        with pytest.raises(InvalidSeasonalModeError):
            holt_winters_forecast(series, season_length=12, mode="invalid")

    def test_invalid_alpha_raises(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        with pytest.raises(ValueError):
            holt_winters_forecast(series, season_length=12, alpha=1.5)

    def test_constant_series_forecast(self):
        series = [5.0] * 48
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=6)
        assert np.allclose(result.forecast, 5.0, atol=0.5)

    def test_linear_trend_forecast(self):
        series = [10 + i * 2.0 for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=6)
        # Forecast should continue the linear trend
        expected = [10 + (48 + i) * 2.0 for i in range(6)]
        assert np.allclose(result.forecast, expected, atol=5.0)


class TestHoltWintersSeasonality:
    """Seasonality handling tests."""

    def test_additive_seasonal_pattern(self):
        # Pure additive seasonality
        season_length = 12
        base = 50.0
        amplitude = 5.0
        series = [base + amplitude * math.sin(2 * math.pi * i / season_length) for i in range(48)]
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=12)
        # Forecast should capture the seasonal pattern
        assert np.all(np.abs(result.forecast - base) < amplitude * 1.5)

    def test_multiplicative_seasonal_pattern(self):
        season_length = 12
        base = 100.0
        amplitude = 0.2
        series = [base * (1 + amplitude * math.sin(2 * math.pi * i / season_length)) for i in range(48)]
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=12, mode="multiplicative")
        assert np.all(result.forecast > 0)
        assert np.all(np.abs(result.forecast - base) < base * amplitude * 1.5)

    def test_seasonal_components_length(self):
        series = [10 + math.sin(i / 3) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=1)
        assert len(result.seasonal) == 12


class TestHoltWintersErrorMetrics:
    """Error metric validation tests."""

    def test_perfect_fit_zero_error(self):
        # Perfect linear model
        series = [10 + i * 2.0 for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=1)
        assert result.mse < 1.0
        assert result.rmse < 1.0
        assert result.mae < 1.0

    def test_mape_finite_for_nonzero(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=1)
        assert math.isfinite(result.mape)

    def test_mape_infinite_for_zero(self):
        series = [0.0] * 48
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=1)
        assert result.mape == float('inf')


class TestDriftDetection:
    """Page-Hinkley drift detector tests."""

    def test_no_drift_stable_series(self):
        detector = DriftDetector(min_instance=30, lambda_threshold=100.0)
        for _ in range(100):
            assert not detector.update(10.0 + np.random.normal(0, 0.1))

    def test_drift_detected_on_shift(self):
        detector = DriftDetector(min_instance=30, lambda_threshold=50.0)
        # Stable phase
        for _ in range(50):
            detector.update(10.0)
        # Drift phase
        drift_detected = False
        for i in range(50):
            if detector.update(10.0 + i * 0.5):
                drift_detected = True
                break
        assert drift_detected

    def test_reset_clears_state(self):
        detector = DriftDetector(min_instance=10, lambda_threshold=10.0)
        for i in range(20):
            detector.update(10.0 + i * 2.0)
        assert detector.drift_detected
        detector.reset()
        assert not detector.drift_detected
        assert detector._count == 0

    def test_min_instance_respected(self):
        detector = DriftDetector(min_instance=100, lambda_threshold=1.0)
        for i in range(50):
            assert not detector.update(10.0 + i * 10.0)  # Huge drift but below min_instance


class TestPropertyBased:
    """Property-based tests using Hypothesis."""

    @given(
        st.lists(st.floats(min_value=1.0, max_value=100.0), min_size=48, max_size=48),
        st.integers(min_value=4, max_value=12),
    )
    @settings(max_examples=50, deadline=None)
    def test_forecast_properties(self, series, season_length):
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=6)
        assert len(result.forecast) == 6
        assert np.all(np.isfinite(result.forecast))
        assert np.all(result.lower_bound <= result.forecast)
        assert np.all(result.forecast <= result.upper_bound)

    @given(
        st.lists(st.floats(min_value=1.0, max_value=100.0), min_size=48, max_size=48),
        st.integers(min_value=4, max_value=12),
    )
    @settings(max_examples=50, deadline=None)
    def test_forecast_bounds_width(self, series, season_length):
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=6)
        widths = result.upper_bound - result.lower_bound
        assert np.all(widths >= 0)
        # Wider intervals for longer horizons
        assert widths[-1] >= widths[0]

    @given(
        st.lists(st.floats(min_value=1.0, max_value=100.0), min_size=48, max_size=48),
    )
    @settings(max_examples=50, deadline=None)
    def test_drift_detector_state(self, series):
        detector = DriftDetector(min_instance=10, lambda_threshold=100.0)
        for value in series:
            detector.update(value)
        assert detector._count == len(series)
        assert detector._mean == pytest.approx(np.mean(series), rel=0.1)


class TestStatisticalValidation:
    """Statistical validation of forecast quality."""

    def test_forecast_residuals_unbiased(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=1)
        # Residuals should be approximately zero-mean
        assert abs(result.level - np.mean(series)) < 5.0

    def test_confidence_interval_coverage(self):
        """95% CI should contain ~95% of actual values in a controlled test."""
        np.random.seed(42)
        season_length = 12
        n = 120
        series = [50 + 10 * math.sin(2 * math.pi * i / season_length) + np.random.normal(0, 2) for i in range(n)]
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=12)
        # Generate actual future values
        actual = [50 + 10 * math.sin(2 * math.pi * (n + i) / season_length) + np.random.normal(0, 2) for i in range(12)]
        coverage = np.mean((actual >= result.lower_bound) & (actual <= result.upper_bound))
        # With 12 points, allow some slack
        assert coverage >= 0.5  # At least 50% coverage (small sample)

    def test_multiplicative_positive_forecast(self):
        series = [100 * (1 + 0.1 * math.sin(i / 3)) for i in range(48)]
        result = holt_winters_forecast(series, season_length=12, forecast_horizon=6, mode="multiplicative")
        assert np.all(result.forecast > 0)


