class TestParameterSensitivity:
    """Parameter sensitivity and optimization tests."""

    def test_alpha_sensitivity(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result_low = holt_winters_forecast(series, season_length=12, alpha=0.1, forecast_horizon=1)
        result_high = holt_winters_forecast(series, season_length=12, alpha=0.9, forecast_horizon=1)
        # Higher alpha should track recent data more closely
        assert result_high.level != result_low.level

    def test_beta_sensitivity(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result_low = holt_winters_forecast(series, season_length=12, beta=0.01, forecast_horizon=1)
        result_high = holt_winters_forecast(series, season_length=12, beta=0.5, forecast_horizon=1)
        assert result_low.trend != result_high.trend

    def test_gamma_sensitivity(self):
        series = [10 + i * 0.5 + math.sin(i / 4) for i in range(48)]
        result_low = holt_winters_forecast(series, season_length=12, gamma=0.01, forecast_horizon=1)
        result_high = holt_winters_forecast(series, season_length=12, gamma=0.5, forecast_horizon=1)
        assert not np.allclose(result_low.seasonal, result_high.seasonal)


class TestDriftDetectionAdvanced:
    """Advanced drift detection scenarios."""

    def test_gradual_drift_detection(self):
        detector = DriftDetector(min_instance=20, lambda_threshold=30.0)
        # Gradual drift
        for i in range(100):
            value = 10.0 + i * 0.1
            detector.update(value)
        assert detector.drift_detected

    def test_abrupt_drift_detection(self):
        detector = DriftDetector(min_instance=20, lambda_threshold=30.0)
        for _ in range(30):
            detector.update(10.0)
        # Abrupt shift
        for i in range(20):
            if detector.update(20.0):
                break
        assert detector.drift_detected

    def test_no_false_positive_stable(self):
        detector = DriftDetector(min_instance=50, lambda_threshold=100.0)
        np.random.seed(123)
        for _ in range(200):
            detector.update(10.0 + np.random.normal(0, 0.5))
        assert not detector.drift_detected

    def test_drift_detection_with_noise(self):
        detector = DriftDetector(min_instance=30, lambda_threshold=50.0)
        np.random.seed(456)
        for _ in range(50):
            detector.update(10.0 + np.random.normal(0, 1.0))
        # Drift with noise
        for i in range(50):
            value = 10.0 + i * 0.3 + np.random.normal(0, 1.0)
            if detector.update(value):
                break
        assert detector.drift_detected


class TestIntegration:
    """Integration-style tests combining components."""

    def test_full_pipeline(self):
        """End-to-end: generate series, forecast, detect drift."""
        np.random.seed(789)
        season_length = 12
        n = 96
        # Generate series with drift in the second half
        series = []
        for i in range(n):
            if i < n // 2:
                series.append(50 + 10 * math.sin(2 * math.pi * i / season_length) + np.random.normal(0, 2))
            else:
                series.append(60 + 10 * math.sin(2 * math.pi * i / season_length) + np.random.normal(0, 2))

        # Forecast on first half
        result = holt_winters_forecast(series[:n // 2], season_length=season_length, forecast_horizon=12)
        assert len(result.forecast) == 12

        # Drift detection on full series
        detector = DriftDetector(min_instance=20, lambda_threshold=30.0)
        drift_points = []
        for i, value in enumerate(series):
            if detector.update(value):
                drift_points.append(i)
        assert len(drift_points) > 0
        # Drift should be detected in the second half
        assert drift_points[0] >= n // 2

    def test_forecast_then_drift(self):
        """Forecast quality degrades after drift, detector catches it."""
        np.random.seed(321)
        season_length = 12
        n = 72
        series = [50 + 10 * math.sin(2 * math.pi * i / season_length) + np.random.normal(0, 2) for i in range(n)]

        # Forecast
        result = holt_winters_forecast(series, season_length=season_length, forecast_horizon=12)
        assert np.all(np.isfinite(result.forecast))

        # Simulate actual future with drift
        actual_future = [70 + 10 * math.sin(2 * math.pi * (n + i) / season_length) + np.random.normal(0, 2) for i in range(12)]

        # Detection on actual future
        detector = DriftDetector(min_instance=5, lambda_threshold=20.0)
        for value in actual_future:
            detector.update(value)
        assert detector.drift_detected


